(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12 + Math.sin((x+y)*0.009+t*0.15)*8;
  const w1y = Math.cos(y*0.019-t*0.27)*18 + Math.sin(x*0.016+t*0.33)*12 + Math.cos((x-y)*0.011-t*0.18)*8;
  const w2x = Math.sin(x*0.035-t*0.5)*6 + Math.cos(y*0.028+t*0.45)*5;
  const w2y = Math.cos(y*0.032+t*0.55)*6 + Math.sin(x*0.025-t*0.4)*5;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0.3],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.25],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 0.35],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.2],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.3],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.28],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1, 0.22],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+4)*40, 0.085, 1.8, 0.32]
  ];
  let aA=0, aB=0, aC=0, iA=0, iB=0;
  for (const [sX, sY, f, sp, ph] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const df = d*f, tsp = t*sp;
    aA += Math.sin(df - tsp + ph);
    aB += Math.sin(df*1.3 - tsp*0.8 + ph*2);
    aC += Math.sin(df*0.6 - tsp*1.2 + ph*0.5);
    iA += Math.sin(df*f*0.7 + tsp*0.6 + 1.5);
    iB += Math.sin(df*f*0.5 + tsp*0.4 + 3.0);
  }
  const n = 8;
  aA/=n; aB/=n; aC/=n; iA/=n; iB/=n;
  const react1 = aA*0.5 + aB*0.3 + aC*0.2;
  const inhib1 = iA*0.6 + iB*0.4;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1) + Math.sin(sx*0.05+sy*0.01-t*0.6))/3;
  const bgFine = (Math.sin(sx*0.12+sy*0.08+t*2.5) + Math.sin(sx*0.09-sy*0.11+t*3.2) + Math.sin((sx+sy)*0.14-t*2.8))*0.2;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2) + Math.sin(dist*0.07-ang*2+t*0.9))*0.28;
  const radialPulse = Math.sin(dist*0.03 - t*2)*0.15*Math.exp(-dist*0.005);
  const crossTerm = Math.sin(aA*Math.PI)*Math.cos(aB*Math.PI)*0.3;
  const rd1 = Math.tanh((react1 - inhib1*0.65 + bg*0.25 + spiral + bgFine + radialPulse + crossTerm)*2.0);
  const rd2 = Math.tanh((aC - iA*0.5 + bg*0.2 - spiral*0.5 + bgFine*0.5)*2.5);
  const coupling = Math.tanh((rd1 + rd2*0.6)*1.8);
  const voronoi = (() => {
    let md = 1e9, md2 = 1e9;
    for (let i = 0; i < 6; i++) {
      const vx = 80 + i*80 + Math.sin(t*0.4+i*1.7)*30;
      const vy = 40 + (i%3)*80 + Math.cos(t*0.35+i*2.1)*25;
      const d = Math.sqrt((sx-vx)**2 + (sy-vy)**2);
      if (d < md) { md2 = md; md = d; } else if (d < md2) { md2 = d; }
    }
    return Math.sin((md2-md)*0.15)*0.4;
  })();
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5 + voronoi)*1.5)*0.25;
  const edge = Math.abs(coupling) > 0.65 ? 1.0 : 0.0;
  const glow = Math.exp(-Math.abs(coupling)*0.5)*0.3;
  const blend = coupling*0.6 + cell*0.15 + edge*0.15 + glow*0.1;
  const v = blend*0.5+0.5;
  const pal = [
    [6,12,42],[12,35,82],[18,72,105],[24,118,128],[45,158,135],
    [120,180,110],[195,185,70],[220,155,60],[210,110,65],[185,65,60],
    [145,38,55],[95,22,48],[50,15,40],[6,12,42]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.85 + Math.sin(coupling*Math.PI)*0.15 + edge*0.15;
  const edgeBoost = edge > 0.5 ? 1.2 : 1.0;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edgeBoost)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edgeBoost)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edgeBoost)|0
  ];
}
